// Summer water season used by the current seed — guarded Minneapolis and
// St. Paul beaches and splash pads run Memorial Day to Labor Day. Month-level:
// the exact lifeguard dates shift yearly (they live on each sourceUrl).
const SUMMER: PlaceSeason = { type: "seasonal", openMonth: 5, closeMonth: 9, label: "Memorial Day–Labor Day" };
// Outdoor pools open a bit later than the lakes (schools out) and close end of
// August — June–August, month-level. Indoor pools run all year; the St. Paul
// indoor water park runs the OFF-season (Sept–May), which wraps the new year.
const POOL_SUMMER: PlaceSeason = { type: "seasonal", openMonth: 6, closeMonth: 8, label: "June–August" };
const YEAR_ROUND: PlaceSeason = { type: "year-round" };
// Golf: MN courses open when the frost is out and close with it — roughly April
// through October, month-level (the exact open/close shifts yearly with weather).
const GOLF_SEASON: PlaceSeason = { type: "seasonal", openMonth: 4, closeMonth: 10, label: "April–October" };
// Farmers markets: the outdoor season runs roughly May–October (a few flagships
// add an indoor winter market, noted per entry). Month-level.
const MARKET_SEASON: PlaceSeason = { type: "seasonal", openMonth: 5, closeMonth: 10, label: "May–October" };
const OFF_SEASON: PlaceSeason = { type: "seasonal", openMonth: 9, closeMonth: 5, label: "September–May (closed summer)" };
// Winter kinds (outdoor rinks, sledding hills) run the cold months, weather
// permitting — the Dec–Feb core, month-level. openMonth > closeMonth wraps the
// new year, so openNow reads them closed all summer and the page shows the
// "closed for the season" banner. Indoor rinks stay YEAR_ROUND.
const WINTER: PlaceSeason = { type: "seasonal", openMonth: 12, closeMonth: 2, label: "December–February" };
// Downhill ski season runs a bit longer than the skating/sledding window —
// roughly December into March, snowmaking permitting. A winter wrap (Dec→Mar),
// like WINTER; openNow handles the year-boundary.
const SKI_SEASON: PlaceSeason = { type: "seasonal", openMonth: 12, closeMonth: 3, label: "December–March" };
// Apple/pumpkin season: pick-your-own opens late summer and runs through the
// pumpkin rush, roughly September–October (month-level; early varieties start in
// August, later ones and the last pumpkins linger into November).
const FALL_SEASON: PlaceSeason = { type: "seasonal", openMonth: 9, closeMonth: 10, label: "September–October" };
// The generic warm-season window (April–October, month-level). Used by the
// hockey-rink/ski-trail dog parks that close for winter ice/snow, and by gated
// seasonal gardens like Eloise Butler. Exact dates shift yearly and live on each
// sourceUrl.
const WARM_SEASON: PlaceSeason = { type: "seasonal", openMonth: 4, closeMonth: 10, label: "April–October" };

